"use client"

import animation from "react-useanimations/lib/notification2"

import { UseAnimation, type UseAnimationProps } from "@/components/use-animation"

// "Notification V2" from https://useanimations.com (MIT): https://useanimations.com/icons/notification-v2
export function AnimatedNotificationV2(
  props: Omit<UseAnimationProps, "animationData">
) {
  return (
    <UseAnimation
      animationData={animation.animationData}
      interaction="click-toggle"
      {...props}
    />
  )
}
